test("calculates lead time demand safety stock and reorder point and recommends a reorder when stock is 360", function () {
  var actual = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 360 });
  assert.deepEqual(actual, { leadTimeDemand: 300, safetyStock: 60, reorderPoint: 360, reorder: true });
});

test("does not recommend a reorder when stock is 361 and above the reorder point", function () {
  var actual = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 361 });
  assert.deepEqual(actual, { leadTimeDemand: 300, safetyStock: 60, reorderPoint: 360, reorder: false });
});

test("recommends a reorder when stock is 359 and below the reorder point", function () {
  var actual = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 359 });
  assert.deepEqual(actual, { leadTimeDemand: 300, safetyStock: 60, reorderPoint: 360, reorder: true });
});

