  assert.deepEqual(actual, { leadTimeDemand: 200, safetyStock: 40, reorderPoint: 240, reorder: true });
});

test("recommends a reorder when stock is 239 and below reorder point 240", function () {
  var actual = code.reorderCheck({ averageDailySales: 25, leadTimeDays: 8, stockOnHand: 239 });
  assert.deepEqual(actual, { leadTimeDemand: 200, safetyStock: 40, reorderPoint: 240, reorder: true });
});

test("does not recommend a reorder when stock is 241 and above reorder point 240", function () {
  var actual = code.reorderCheck({ averageDailySales: 25, leadTimeDays: 8, stockOnHand: 241 });
