test("calculates a one day lead time demand of 15 and recommends a reorder when stock is 18", function () {
  var actual = code.reorderCheck({ averageDailySales: 15, leadTimeDays: 1, stockOnHand: 18 });
  assert.deepEqual(actual, { leadTimeDemand: 15, safetyStock: 3, reorderPoint: 18, reorder: true });
});

test("calculates a ten day lead time demand of 10 and recommends a reorder when stock is 12", function () {
  var actual = code.reorderCheck({ averageDailySales: 1, leadTimeDays: 10, stockOnHand: 12 });
  assert.deepEqual(actual, { leadTimeDemand: 10, safetyStock: 2, reorderPoint: 12, reorder: true });
});

test("recommends a reorder when stock on hand is 0 and below reorder point 144", function () {
  var actual = code.reorderCheck({ averageDailySales: 40, leadTimeDays: 3, stockOnHand: 0 });
  assert.deepEqual(actual, { leadTimeDemand: 120, safetyStock: 24, reorderPoint: 144, reorder: true });
});

test("throws unknown field when the input includes region", function () {
  assert.throws(function () {
    code.reorderCheck({ region: 9, averageDailySales: 50, leadTimeDays: 6, stockOnHand: 360 });
  }, /^unknown field: region$/);
});

